  "ex",
  "ch",
  "ic",
  "cap",
  "rex",
  "rcap",
  "rch",
  "ric",
  "rem",
  "lh",
  "rlh",
  "vw",
  "vh",
  "vi",
  "vb",
  "vmin",
  "vmax",
  // Small, large and dynamic viewport units are resolved by the browser.
  "svw",
  "svh",
  "svi",
  "svb",
  "svmin",
  "svmax",
  "lvw",
  "lvh",
  "lvi",
  "lvb",
  "lvmin",
