export class AllShorthandValidator extends SimpleShorthandValidator {
  refreshPropList(): void {
    this.propList = this.validatorSet.getPropertiesForAll();
  }

  override validateList(list: Css.Val[]): number {
    this.error = true;
    return 0;
  }
}

export const shorthandValidators: {
  [key: string]: typeof ShorthandValidator;
} = {
  SIMPLE: SimpleShorthandValidator,
  INSETS: InsetsShorthandValidator,
  INSETS_SLASH: InsetsSlashShorthandValidator,
  COMMA: CommaShorthandValidator,
  FONT: FontShorthandValidator,
  TEXT_SPACING: TextSpacingShorthandValidator,
  ALL: AllShorthandValidator,
};

//---- validation grammar parser and public property validator
//------------------------

const propsBrowserDependent = ["initial-letter"];

/**
 * Object that validates simple and shorthand properties, breaking up shorthand
 * properties into corresponding simple ones, also stripping property prefixes.
 */
export class ValidatorSet {
  validators = new Map<string, PropertyValidator>();
  prefixes = new Map<string, Set<string>>();
  defaultValues = new Map<string, Css.Val>();
  namedValidators = new Map<string, ValidatingGroup>();
  systemFonts = new Map<string, ValueMap>();
  shorthands = new Map<string, ShorthandValidator>();
  layoutProps = new Map<string, Css.Val>();
  backgroundProps = new Map<string, Css.Val>();
  private browserShorthandStyle: CSSStyleDeclaration | null = null;
  private browserShorthandMisses = new Set<string>();
  private browserPropertyNamesForAll: string[] | null = null;
  private allPropertyNames: string[] | null = null;

  private invalidateAllPropertyNames(): void {
    this.allPropertyNames = null;
  }

  private getBrowserPropertyNamesForAll(): string[] | null {
    if (this.browserPropertyNamesForAll) {
      return this.browserPropertyNamesForAll;
    }
    if (
      typeof document === "undefined" ||
      typeof getComputedStyle !== "function"
    ) {
      return null;
    }
    const root = document.documentElement;
    if (!root) {
      return null;
    }
    const computedStyle = getComputedStyle(root);
    const names: string[] = [];
    for (let i = 0; i < computedStyle.length; i++) {
      const name = computedStyle.item(i);
      if (
        !name ||
        Css.isCustomPropName(name) ||
        propsExcludedFromAll.includes(name)
      ) {
        continue;
      }
      names.push(name);
    }
    this.browserPropertyNamesForAll = names;
    return this.browserPropertyNamesForAll;
  }

  getPropertiesForAll(): string[] {
    if (this.allPropertyNames) {
      return this.allPropertyNames;
    }
    const names = new Set<string>();
    for (const name of this.validators.keys()) {
      if (!propsExcludedFromAll.includes(name)) {
        names.add(name);
      }
    }
    const browserPropertyNames = this.getBrowserPropertyNamesForAll();
    if (browserPropertyNames) {
      for (const name of browserPropertyNames) {
        if (this.shorthands.has(name)) {
          continue;
        }
        names.add(name);
      }
    }
    const propList = Array.from(names);
    if (browserPropertyNames) {
      this.allPropertyNames = propList;
    }
    return propList;
  }

  private getBrowserShorthandStyle(): CSSStyleDeclaration | null {
    if (this.browserShorthandStyle !== null) {
      return this.browserShorthandStyle;
    }
    if (typeof document === "undefined") {
      return null;
    }
    this.browserShorthandStyle = document.createElement("div").style;
    return this.browserShorthandStyle;
  }

  expandBrowserShorthand(
    name: string,
    valueText: string,
  ): { propList: string[]; values: { [key: string]: string } } | null {
    const style = this.getBrowserShorthandStyle();
    if (!style) {
      return null;
    }
    style.cssText = "";
    style.setProperty(name, valueText);
    const propList = Array.from({ length: style.length }, (_, i) =>
      style.item(i),
    ).filter((prop): prop is string => !!prop);
    if (
      !propList.length ||
      (propList.length === 1 && propList[0] === name.toLowerCase())
    ) {
      return null;
    }
    // Use a detached CSSStyleDeclaration as a browser-native shorthand parser,
    // then feed the resulting longhand values back into Vivliostyle's cascade.
    const values: { [key: string]: string } = {};
    for (const prop of propList) {
      values[prop] = style.getPropertyValue(prop);
    }
    return { propList, values };
  }

  getShorthand(
    name: string,
    value?: Css.Val | string,
  ): ShorthandValidator | null {
    if (Css.isCustomPropName(name)) {
      return null;
    }
    // CSS property names are ASCII case-insensitive, and callers may pass a
    // name that kept the author's casing, so normalize before every lookup.
    name = name.toLowerCase();
    const shorthand = this.shorthands.get(name);
    if (shorthand) {
      if (
        shorthand instanceof AllShorthandValidator &&
        !this.allPropertyNames
      ) {
        shorthand.refreshPropList();
      }
      return shorthand;
    }
    if (this.validators.has(name)) {
      // Vivliostyle has its own validator for this property and looks it up by
      // this name after the cascade, so it must not be split into the browser's
      // longhands even when the browser treats it as a shorthand
      // (e.g. `background-position` → `background-position-x`/`-y`).
      return null;
    }
    if (this.browserShorthandMisses.has(name)) {
      return null;
    }
    if (value == null) {
      return null;
    }
    const expanded = this.expandBrowserShorthand(
      name,
      typeof value === "string" ? value : value.toString(),
    );
    if (!expanded) {
      if (
        typeof value === "string"
          ? !/\bvar\(/i.test(value)
          : !containsVar(value)
      ) {
        this.browserShorthandMisses.add(name);
      }
      return null;
    }
    const browserShorthand = new BrowserShorthandValidator(
      this,
      name,
      expanded.propList,
    );
    this.shorthands.set(name, browserShorthand);
    this.invalidateAllPropertyNames();
    return browserShorthand;
  }

  private addReplacement(
    val: ValidatingGroup,
    token: CssTokenizer.Token,
  ): ValidatingGroup {
    let cssval: Css.Val;
    if (token.type == TokenType.NUMERIC) {
      cssval = new Css.Numeric(token.num, token.text);
    } else if (token.type == TokenType.HASH) {
      cssval = new Css.HexColor(token.text);
    } else if (token.type == TokenType.IDENT) {
      cssval = Css.getName(token.text);
    } else {
      throw new Error("unexpected replacement");
    }
    if (val.isPrimitive()) {
      const validator = val.nodes[0].validator as PrimitiveValidator;
      const idents = validator.idents;
      for (const ident in idents) {
        idents[ident] = cssval;
      }
      return val;
    }
    throw new Error("unexpected replacement");
  }

  private newGroup(op: string, vals: ValidatingGroup[]): ValidatingGroup {
    const group = new ValidatingGroup();
    if (op == "||") {
      for (let i = 0; i < vals.length; i++) {
        const subgroup = new ValidatingGroup();
        subgroup.startClause(i);
        subgroup.addGroup(vals[i], Add.FOLLOW);
        subgroup.endClause(i);
        group.addGroup(subgroup, i == 0 ? Add.FOLLOW : Add.ALTERNATE);
      }
      const outer = new ValidatingGroup();
      outer.startSpecialGroup();
      outer.addGroup(group, Add.REPEATED);
      outer.endSpecialGroup();
      return outer;
    } else {
      let how: Add;
      switch (op) {
        case " ":
          how = Add.FOLLOW;
          break;
        case "|":
        case "||":
          how = Add.ALTERNATE;
          break;
        default:
          throw new Error("unexpected op");
      }
      for (let i = 0; i < vals.length; i++) {
        group.addGroup(vals[i], i == 0 ? Add.FOLLOW : how);
      }
      return group;
    }
  }

  private addCounts(
    val: ValidatingGroup,
    min: number,
    max: number,
  ): ValidatingGroup {
    const group = new ValidatingGroup();
    for (let i = 0; i < min; i++) {
      group.addGroup(val.clone(), Add.FOLLOW);
    }
    if (max == Number.POSITIVE_INFINITY) {
      group.addGroup(val, Add.REPEATED);
    } else {
      for (let i = min; i < max; i++) {
        group.addGroup(val.clone(), Add.OPTIONAL);
      }
    }
    return group;
  }

  private primitive(validator: PropertyValidator): ValidatingGroup {
    const group = new ValidatingGroup();
    group.addPrimitive(validator);
    return group;
  }

  private newFunc(
    fn: string | undefined,
    val: ValidatingGroup,
  ): ValidatingGroup {
    let validator: PropertyValidator;
    switch (fn) {
      case "COMMA":
        validator = new CommaListValidator(val);
        break;
      case "SPACE":
        validator = new SpaceListValidator(val);
        break;
      case "attr":
        validator = new AttrFuncValidator();
        break;
      default:
        validator = new FuncValidator(fn.toLowerCase(), val);
        break;
    }
    return this.primitive(validator);
  }

  initBuiltInValidators(): void {
    this.namedValidators.set(
      "COLOR",
      this.primitive(new PrimitiveValidator(ALLOW_COLOR, NO_IDENTS, NO_IDENTS)),
    );
    this.namedValidators.set("ATTR", this.primitive(new AttrFuncValidator()));
    this.namedValidators.set(
      "IMAGE_FUNCTION",
      this.primitive(new PrimitiveValidator(ALLOW_IMAGE, NO_IDENTS, NO_IDENTS)),
    );
    this.namedValidators.set(
      "POS_INT",
      this.primitive(
        new PrimitiveValidator(ALLOW_POS_INT, NO_IDENTS, NO_IDENTS),
      ),
    );
    this.namedValidators.set(
      "POS_NUM",
      this.primitive(
        new PrimitiveValidator(ALLOW_POS_NUM, NO_IDENTS, NO_IDENTS),
      ),
    );
    this.namedValidators.set(
      "POS_PERCENTAGE",
      this.primitive(
        new PrimitiveValidator(ALLOW_POS_NUMERIC, NO_IDENTS, PERCENTAGE_UNITS),
      ),
    );
    this.namedValidators.set(
      "NEGATIVE",
      this.primitive(
        new PrimitiveValidator(ALLOW_NEGATIVE, NO_IDENTS, NO_IDENTS),
      ),
    );
    this.namedValidators.set(
      "ZERO",
      this.primitive(new PrimitiveValidator(ALLOW_ZERO, NO_IDENTS, NO_IDENTS)),
    );
    this.namedValidators.set(
      "ZERO_PERCENTAGE",
      this.primitive(
        new PrimitiveValidator(ALLOW_ZERO_PERCENT, NO_IDENTS, NO_IDENTS),
      ),
    );
    this.namedValidators.set(
      "POS_LENGTH",
      this.primitive(
        new PrimitiveValidator(ALLOW_POS_NUMERIC, NO_IDENTS, LENGTH_UNITS),
      ),
    );
    this.namedValidators.set(
      "POS_ANGLE",
      this.primitive(
        new PrimitiveValidator(ALLOW_POS_NUMERIC, NO_IDENTS, ANGLE_UNITS),
      ),
    );
    this.namedValidators.set(
      "POS_TIME",
      this.primitive(
        new PrimitiveValidator(ALLOW_POS_NUMERIC, NO_IDENTS, TIME_UNITS),
      ),
    );
    this.namedValidators.set(
      "FREQUENCY",
      this.primitive(
        new PrimitiveValidator(ALLOW_POS_NUMERIC, NO_IDENTS, FREQUENCY_UNITS),
      ),
    );
    this.namedValidators.set(
      "RESOLUTION",
      this.primitive(
        new PrimitiveValidator(ALLOW_POS_NUMERIC, NO_IDENTS, {
          dpi: Css.empty,
          dpcm: Css.empty,
          dppx: Css.empty,
        }),
      ),
    );
    this.namedValidators.set(
      "URI",
      this.primitive(new PrimitiveValidator(ALLOW_URL, NO_IDENTS, NO_IDENTS)),
    );
    this.namedValidators.set(
      "URANGE",
      this.primitive(
        new PrimitiveValidator(ALLOW_URANGE, NO_IDENTS, NO_IDENTS),
      ),
    );
    this.namedValidators.set(
      "IDENT",
      this.primitive(new PrimitiveValidator(ALLOW_IDENT, NO_IDENTS, NO_IDENTS)),
    );
    this.namedValidators.set(
      "STRING",
      this.primitive(new PrimitiveValidator(ALLOW_STR, NO_IDENTS, NO_IDENTS)),
    );
    this.namedValidators.set(
      "SLASH",
      this.primitive(new PrimitiveValidator(ALLOW_SLASH, NO_IDENTS, NO_IDENTS)),
    );
    const stdfont = { "font-family": Css.getName("sans-serif") };
    this.systemFonts.set("caption", stdfont);
    this.systemFonts.set("icon", stdfont);
    this.systemFonts.set("menu", stdfont);
    this.systemFonts.set("message-box", stdfont);
    this.systemFonts.set("small-caption", stdfont);
    this.systemFonts.set("status-bar", stdfont);
  }

  private isBuiltIn(name: string): boolean {
    return !!name.match(/^[A-Z_0-9]+$/);
  }

  private readNameAndPrefixes(
    tok: CssTokenizer.Tokenizer,
    section: number,
  ): string | null {
    let token = tok.token();
    if (token.type == TokenType.EOF) {
      // Finished normally
      return null;
    }
    const rulePrefixes = new Set([""]);
    if (token.type == TokenType.O_BRK) {
      do {
        tok.consume();
        token = tok.token();
        if (token.type != TokenType.IDENT) {
          throw new Error("Prefix name expected");
        }
        rulePrefixes.add(token.text);
        tok.consume();
        token = tok.token();
      } while (token.type == TokenType.COMMA);
      if (token.type != TokenType.C_BRK) {
        throw new Error("']' expected");
      }
      tok.consume();
      token = tok.token();
    }
    if (token.type != TokenType.IDENT) {
      throw new Error("Property name expected");
    }
    if (section == 2 ? token.text == "SHORTHANDS" : token.text == "DEFAULTS") {
      tok.consume();
      return null;
    }
    const name = token.text;
    tok.consume();
    if (section != 2) {
      if (tok.token().type != TokenType.EQ) {
        throw new Error("'=' expected");
      }
      if (!this.isBuiltIn(name)) {
        this.prefixes.set(name, rulePrefixes);
      }
    } else {
      if (tok.token().type != TokenType.COLON) {
        throw new Error("':' expected");
      }
    }
    return name;
  }

  private parseValidators(tok: CssTokenizer.Tokenizer): void {
    while (true) {
      const ruleName = this.readNameAndPrefixes(tok, 1);
      if (!ruleName) {
        return;
      }
      let vals: ValidatingGroup[] = [];
      const stack: {
        vals: ValidatingGroup[];
        op: string;
        b: string;
        fn?: string;
      }[] = [];
      let op = "";
      let val: ValidatingGroup;
      let expectval = true;
      const reduce = (): ValidatingGroup => {
        if (vals.length == 0) {
          throw new Error("No values");
        }
        if (vals.length == 1) {
          return vals[0];
        }
        return this.newGroup(op, vals);
      };
      const setop = (currop: string): void => {
        if (expectval) {
          throw new Error(`'${currop}': unexpected`);
        }
        if (op && op != currop) {
          throw new Error(`mixed operators: '${currop}' and '${op}'`);
        }
        op = currop;
        expectval = true;
      };
      let result: ValidatingGroup | null = null;
      while (!result) {
        tok.consume();
        let token = tok.token();
        switch (token.type) {
          case TokenType.IDENT:
            if (!expectval) {
              setop(" ");
            }
            if (this.isBuiltIn(token.text)) {
              const builtIn = this.namedValidators.get(token.text);
              if (!builtIn) {
                throw new Error(`'${token.text}' unexpected`);
              }
              vals.push(builtIn.clone());
            } else {
              const idents: ValueMap = {};
              idents[token.text.toLowerCase()] = Css.getName(token.text);
              vals.push(
                this.primitive(new PrimitiveValidator(0, idents, NO_IDENTS)),
              );
            }
            expectval = false;
            break;
          case TokenType.INT: {
            const idents: ValueMap = {};
            idents[`${token.num}`] = new Css.Int(token.num);
            vals.push(
              this.primitive(new PrimitiveValidator(0, idents, NO_IDENTS)),
            );
            expectval = false;
            break;
          }
          case TokenType.BAR:
            setop("|");
            break;
          case TokenType.BAR_BAR:
            setop("||");
            break;
          case TokenType.O_BRK:
            if (!expectval) {
              setop(" ");
            }
            stack.push({ vals, op, b: "[" });
            op = "";
            vals = [];
            expectval = true;
            break;
          case TokenType.FUNC:
            if (!expectval) {
              setop(" ");
            }
            stack.push({ vals, op, b: "(", fn: token.text });
            op = "";
            vals = [];
            expectval = true;
            break;
          case TokenType.C_BRK: {
            val = reduce();
            const open = stack.pop();
            if (open.b != "[") {
              throw new Error("']' unexpected");
            }
            vals = open.vals;
            vals.push(val);
            op = open.op;
            expectval = false;
            break;
          }
          case TokenType.C_PAR: {
            val = reduce();
            const open = stack.pop();
            if (open.b != "(") {
              throw new Error("')' unexpected");
            }
            vals = open.vals;
            vals.push(this.newFunc(open.fn, val));
            op = open.op;
            expectval = false;
            break;
          }
          case TokenType.COLON:
            if (expectval) {
              throw new Error("':' unexpected");
            }
            tok.consume();
            vals.push(this.addReplacement(vals.pop(), tok.token()));
            break;
          case TokenType.QMARK:
            if (expectval) {
              throw new Error("'?' unexpected");
            }
            vals.push(this.addCounts(vals.pop(), 0, 1));
            break;
          case TokenType.STAR:
            if (expectval) {
              throw new Error("'*' unexpected");
            }
            vals.push(this.addCounts(vals.pop(), 0, Number.POSITIVE_INFINITY));
            break;
          case TokenType.PLUS:
            if (expectval) {
              throw new Error("'+' unexpected");
            }
            vals.push(this.addCounts(vals.pop(), 1, Number.POSITIVE_INFINITY));
            break;
          case TokenType.O_BRC: {
            tok.consume();
            token = tok.token();
            if (token.type != TokenType.INT) {
              throw new Error("<int> expected");
            }
            const min = token.num;
            let max = min;
            tok.consume();
            token = tok.token();
            if (token.type == TokenType.COMMA) {
              tok.consume();
              token = tok.token();
              if (token.type != TokenType.INT) {
                throw new Error("<int> expected");
              }
              max = token.num;
              tok.consume();
              token = tok.token();
            }
            if (token.type != TokenType.C_BRC) {
              throw new Error("'}' expected");
            }
            vals.push(this.addCounts(vals.pop(), min, max));
            break;
          }
          case TokenType.SEMICOL:
            result = reduce();
            if (stack.length > 0) {
              throw new Error(`unclosed '${stack.pop().b}'`);
            }
            break;
          default:
            throw new Error("unexpected token");
        }
      }
      tok.consume();
      if (this.isBuiltIn(ruleName)) {
        this.namedValidators.set(ruleName, result);
      } else {
        if (result.isSimple()) {
          this.validators.set(ruleName, result.nodes[0].validator);
        } else {
          this.validators.set(ruleName, new SpaceListValidator(result));
        }
      }
    }
  }

  private parseDefaults(tok: CssTokenizer.Tokenizer): void {
    while (true) {
      const propName = this.readNameAndPrefixes(tok, 2);
      if (!propName) {
        return;
      }
      const vals: Css.Val[] = [];
      while (true) {
        tok.consume();
        const token = tok.token();
        if (token.type == TokenType.SEMICOL) {
          tok.consume();
          break;
        }
        switch (token.type) {
          case TokenType.IDENT:
            vals.push(Css.getName(token.text));
            break;
          case TokenType.NUM:
            vals.push(new Css.Num(token.num));
            break;
          case TokenType.INT:
            vals.push(new Css.Int(token.num));
            break;
          case TokenType.NUMERIC:
            vals.push(new Css.Numeric(token.num, token.text));
            break;
          default:
            throw new Error("unexpected token");
        }
      }
      this.defaultValues.set(
        propName,
        vals.length > 1 ? new Css.SpaceList(vals) : vals[0],
      );
    }
  }

  private parseShorthands(tok: CssTokenizer.Tokenizer): void {
    while (true) {
      const ruleName = this.readNameAndPrefixes(tok, 3);
      if (!ruleName) {
        return;
      }
      let token = tok.nthToken(1);
      let validatorClass: typeof ShorthandValidator;
      if (token.type == TokenType.IDENT && shorthandValidators[token.text]) {
        validatorClass = shorthandValidators[token.text];
        tok.consume();
      } else {
        validatorClass = SimpleShorthandValidator;
      }
      let result = false;
      let syntax: ShorthandSyntaxNode[] = [];
      let slash = false;
      const stack: { slash: boolean; syntax: ShorthandSyntaxNode[] }[] = [];
      const propList: string[] = [];
      while (!result) {
        tok.consume();
        token = tok.token();
        switch (token.type) {
          case TokenType.IDENT:
            if (this.validators.has(token.text)) {
              syntax.push(new ShorthandSyntaxProperty(this, token.text));
              // `font-variant_css2` and `font-stretch_css3` are not real properties
              if (!token.text.includes("_")) {
                propList.push(token.text);
              }
            } else if (
              this.shorthands.get(token.text) instanceof
              InsetsShorthandValidator
            ) {
              const insetShorthand = this.shorthands.get(
                token.text,
              ) as InsetsShorthandValidator;
              syntax.push(insetShorthand.createSyntaxNode());
              propList.push(...insetShorthand.propList);
            } else {
              throw new Error(
                `'${token.text}' is neither a simple property nor an inset shorthand`,
              );
            }
            break;
          case TokenType.SLASH:
            if (syntax.length > 0 || slash) {
              throw new Error("unexpected slash");
            }
            slash = true;
            break;
          case TokenType.O_BRK:
            stack.push({ slash, syntax });
            syntax = [];
            slash = false;
            break;
          case TokenType.C_BRK: {
            const compound = new ShorthandSyntaxCompound(syntax, slash);
            const item = stack.pop();
            syntax = item.syntax;
            slash = item.slash;
            syntax.push(compound);
            break;
          }
          case TokenType.SEMICOL:
            result = true;
            tok.consume();
            break;
          default:
            throw new Error("unexpected token");
        }
      }
      const shorthandValidator = validatorClass.create(this, syntax, propList);
      this.shorthands.set(ruleName, shorthandValidator);
      this.invalidateAllPropertyNames();
    }
  }

  parse(text: string): void {
    // Not as robust as CSS parser.
    const tok = new CssTokenizer.Tokenizer(text, null);
    this.parseValidators(tok);
    this.parseDefaults(tok);
    this.parseShorthands(tok);
    this.backgroundProps = this.makePropSet(["background"]);
    this.layoutProps = this.makePropSet([
      "margin",
      "border",
      "padding",
      "columns",
      "column-gap",
      "column-rule",
      "column-fill",
    ]);
  }

  makePropSet(propList: string[]): Map<string, Css.Val> {
    const map = new Map<string, Css.Val>();
    for (const prop of propList) {
      const shorthand = this.shorthands.get(prop);
      const list = shorthand ? shorthand.propList : [prop];
      for (const pname of list) {
        map.set(pname, this.defaultValues.get(pname) ?? Css.ident.initial);
      }
    }
    return map;
  }

  validatePropertyAndHandleShorthand(
    name: string,
    value: Css.Val,
    important: boolean,
    scope: Exprs.LexicalScope,
    receiver: PropertyReceiver,
  ): void {
    const ruleType = (receiver as PropertyReceiver & { ruleType?: string })
      .ruleType;
    if (
      Css.isCustomPropName(name) ||
      // Check if it is a `@font-face` descriptor (Issue #1307)
      ruleType === "font-face"
    ) {
      receiver.simpleProperty(name, value, important);
      return;
    }
    if (ruleType === "counter-style") {
      if (CounterStyle.validateDescriptorValue(name, value)) {
        receiver.simpleProperty(name, value, important);
      } else {
        receiver.invalidPropertyValue(name, value);
      }
      return;
    }
    let prefix = "";
    const origName = name;
    name = name.toLowerCase();
    const r = name.match(/^-([a-z]+)-([-a-z0-9]+)$/);
    if (r) {
      prefix = r[1];
      name = r[2];
    }
    const shorthandName = prefix ? origName : name;
    if (containsVar(value)) {
      // Register browser-supported shorthands before var() resolution so the
      // later cascade pass can still expand mixed shorthand/longhand usage.
      this.getShorthand(shorthandName, value);
      // Store the declaration under the name the rest of the engine looks up.
      // The non-var path below stores the lowercased name for properties
      // Vivliostyle validates itself, and consumers such as passPostProperties
      // and transferPropsToRoot() look them up that way.
      receiver.simpleProperty(shorthandName, value, important);
      return;
    }
    if (
      isEngineEvaluatedLengthProperty(name, ruleType === "page") &&
      containsBrowserViewportUnit(value)
    ) {
      // These values are evaluated numerically by the engine and never
      // reach the browser. Keep browser-only viewport units out of page
      // geometry or float limits, but allow them in browser CSS/shorthands.
      receiver.invalidPropertyValue(origName, value);
      return;
    }
    const px = this.prefixes.get(name);
    // The rollback keywords (`revert`, `revert-layer` and `revert-rule`) are
    // resolved by Vivliostyle's own cascade rather than handed to the browser,
    // so whether this browser build happens to support the keyword must not
    // decide whether the declaration is valid, nor how a shorthand expands.
    // Probe the property with `unset` instead, which every browser accepts
    // wherever a CSS-wide keyword is allowed.
    const probeText = Css.isRollbackValue(value) ? "unset" : value.toString();
    if (!px || !px.has(prefix)) {
      if (CSS.supports(origName, probeText)) {
        const shorthand = this.getShorthand(shorthandName, probeText)?.clone(
          scope,
        );
        if (shorthand) {
          if (Css.isDefaultingValue(value)) {
            shorthand.propagateDefaultingValue(value, important, receiver);
          } else {
            value.visit(shorthand);
            if (!shorthand.finish(important, receiver)) {
              receiver.invalidPropertyValue(origName, value);
            }
          }
        } else {
          // Browser supports this property
          receiver.simpleProperty(origName, value, important);
        }
      } else if (prefix && !Base.knownPrefixes.includes(`-${prefix}-`)) {
        // Ignore properties with unknown prefix to avoid unnecessary warnings
      } else {
        receiver.unknownProperty(origName, value);
      }
      return;
    } else if (propsBrowserDependent.includes(name)) {
      // For properties whose support depends on browser, check via CSS.supports
      if (
        !Array.from(px).some((p) =>
          Base.checkIfPropertySupported(p ? `-${p}-` : "", name),
        )
      ) {
        receiver.unknownProperty(origName, value);
        return;
      }
    }
    const validator = this.validators.get(name);
    if (validator) {
      const rvalue =
        Css.isDefaultingValue(value) || value.isExpr()
          ? value
          : value.visit(validator);
      if (rvalue) {
        receiver.simpleProperty(name, rvalue, important);
      } else if (
        !prefix &&
        CSS.supports(name, Css.withoutPageViewportUnits(value.toString()))
      ) {
        // Browser supports this property value, possibly with an internal page
        // viewport unit of this engine, which this engine resolves itself.
        // (Review)
        receiver.simpleProperty(name, value, important);
      } else {
        receiver.invalidPropertyValue(origName, value);
      }
    } else {
      const shorthand = this.getShorthand(name, value)?.clone(scope);
      if (!shorthand) {
        receiver.unknownProperty(origName, value);
        return;
      }
      if (Css.isDefaultingValue(value)) {
        shorthand.propagateDefaultingValue(value, important, receiver);
      } else {
        value.visit(shorthand);
        if (!shorthand.finish(important, receiver)) {
          receiver.invalidPropertyValue(origName, value);
        }
      }
    }
  }
}

export function baseValidatorSet(): ValidatorSet {
  const validatorSet = new ValidatorSet();
  validatorSet.initBuiltInValidators();
  validatorSet.parse(ValidationTxt);
  return validatorSet;
}

/** Browser-only viewport lengths cannot be evaluated numerically by the engine. */
export function containsBrowserViewportUnit(value: Css.Val): boolean {
  const visitor = new BrowserViewportUnitVisitor();
  value.visit(visitor);
  return visitor.found;
}

/** Whether a length needs engine evaluation, optionally in a page-box context. */
export function isEngineEvaluatedLengthProperty(
  name: string,
  pageBox = false,
): boolean {
  name = name.toLowerCase().replace(/^-epubx-/, "");
  return (
    [
      "bleed",
      "crop-offset",
      "float-min-wrap-block",
      "min-page-height",
      "min-page-width",
      "size",
      "snap-height",
      "snap-width",
    ].includes(name) ||
    (pageBox &&
      ([
        "top",
        "right",
        "bottom",
        "left",
        "columns",
        "column-width",
        "column-gap",
        "column-rule",
        "column-rule-width",
        "shape-inside",
        "shape-outside",
      ].includes(name) ||
        /^(?:min-|max-)?(?:width|height|block-size|inline-size)$/.test(name) ||
        /^inset(-|$)/.test(name) ||
        /^(margin|padding)(-|$)/.test(name) ||
        /^border(?:-(?:top|right|bottom|left|block|inline)(?:-(?:start|end))?)?(?:-width)?$/.test(
          name,
        )))
  );
}

class BrowserViewportUnitVisitor extends Css.Visitor {
  found = false;

  override visitNumeric(numeric: Css.Numeric): Css.Val | null {
    this.found ||= /^[sld]v(?:[whbi]|min|max)$/i.test(numeric.unit);
    return null;
  }
}

class VarCheckVisitor extends Css.Visitor {
  varFound = false;

  visitFunc(func: Css.Func): Css.Val | null {
    if (func.name === "var") {
      this.varFound = true;
    } else if (!this.varFound) {
      this.visitValues(func.values);
    }
    return null;
  }
}

export function containsVar(val: Css.Val): boolean {
  const varCheckVisitor = new VarCheckVisitor();
  val.visit(varCheckVisitor);
  return varCheckVisitor.varFound;
}
